"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { Activity, ArrowLeft, ArrowRight, BadgeDollarSign, Bell, CalendarDays, CheckCircle2, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardList, Download, FileText, LayoutDashboard, LockKeyhole, Package, Printer, Settings2, ShieldAlert, Users, Wallet, type LucideIcon } from "lucide-react";
import { AdminBookingDetail, AdminBookings } from "@/components/CoreFlow";
import { FormState, ListState, type FormStatus } from "@/components/StatePatterns";
import { StatusBadge } from "@/components/StatusBadge";
import { formatDate, formatETB, formatMonthYear, formatNumber } from "@/lib/format";
import { mockNotifications, vendorCategories, type AdminStaff, type Booking, type Customer, type FeeStatement, type Venue, type Vendor, type VendorStatus } from "@/lib/mock-data";
import { t } from "@/lib/i18n";
import { useDemo, type AuditRecord } from "@/lib/store";

const todayISO = () => new Date().toISOString().slice(0, 10);
const categoryKeys: Record<string, string> = { Photography: "categoryPhotography", Catering: "categoryCatering", Decor: "categoryDecor", "Music & sound": "categoryMusic", Beauty: "categoryBeauty", Video: "categoryVideo", Flowers: "categoryFlowers" };
const venueTypeKeys: Record<string, string> = { "Wedding hall": "venueWeddingHall", "Garden venue": "venueGarden", "Conference space": "venueConference", "Hotel ballroom": "venueBallroom" };
const statusValues = ["Requested", "Reserved", "Confirmed", "Completed", "Canceled", "New", "Responded", "Declined", "Active", "Pending", "Suspended", "Success", "Failure", "Failed", "Refunded", "Paid", "Outstanding", "Waived", "Needs reschedule or reject", "Needs changes", "Rejected", "Approved"];
function categoryLabel(value: string, locale: "en" | "am") { return categoryKeys[value] ? t(categoryKeys[value], locale) : value; }
function venueTypeLabel(value: string, locale: "en" | "am") { return venueTypeKeys[value] ? t(venueTypeKeys[value], locale) : value; }
function staffRoleLabel(value: string, locale: "en" | "am") { return t(value === "Super Admin" ? "superAdmin" : value === "Venue Manager" ? "venueManager" : value === "Vendor Manager" ? "vendorManager" : "finance", locale); }
const moduleForPath = (path: string) => path.split("/").filter(Boolean)[1] || "dashboard";
const moduleNames: Record<string, string> = {
  dashboard: "adminDashboard", bookings: "bookingTable", calendar: "calendarOverview", venues: "venuesAdmin", vendors: "vendorsAdmin", categories: "categories", customers: "customersAdmin", inquiries: "inquiryAdmin", payments: "paymentsAdmin", revenue: "revenue", reports: "reports", users: "usersRoles", notifications: "notificationCenter", settings: "settingsLabel", audit: "auditLog", content: "contentEditor",
};
const adminNav = [
  ["/admin", "dashboard", LayoutDashboard], ["/admin/bookings", "bookings", ClipboardList], ["/admin/calendar", "calendar", CalendarDays],
  ["/admin/venues", "venues", Package], ["/admin/vendors", "vendors", Users], ["/admin/categories", "categories", Settings2], ["/admin/customers", "customers", Users],
  ["/admin/inquiries", "inquiries", ClipboardList], ["/admin/payments", "payments", Wallet], ["/admin/revenue", "revenue", BadgeDollarSign], ["/admin/reports", "reports", FileText],
  ["/admin/users", "users", Users], ["/admin/notifications", "notifications", Bell], ["/admin/settings", "settings", Settings2], ["/admin/audit", "audit", Activity], ["/admin/content", "content", FileText],
] as const;
const roleModules: Record<string, string[]> = {
  "Super Admin": ["dashboard", "bookings", "calendar", "venues", "vendors", "categories", "customers", "inquiries", "payments", "revenue", "reports", "users", "notifications", "settings", "audit", "content"],
  "Venue Manager": ["dashboard", "bookings", "calendar", "venues", "reports", "notifications"],
  "Vendor Manager": ["dashboard", "vendors", "categories", "customers", "inquiries", "reports", "notifications"],
  Finance: ["dashboard", "payments", "revenue", "reports", "notifications"],
};

function AdminFrame({ pathname, children }: { pathname: string; children: React.ReactNode }) {
  const { locale, staffRole } = useDemo();
  const currentModule = moduleForPath(pathname);
  const allowed = roleModules[staffRole] || roleModules["Super Admin"];
  return <div className="admin-workspace">
    <aside className="admin-sidebar" aria-label={t("adminNavigation", locale)}>
      <div className="admin-sidebar-heading"><span className="admin-sidebar-mark" aria-hidden="true">A</span><div><strong>{t("admin", locale)}</strong><small>{t("demoLabel", locale)} · {t(staffRole === "Super Admin" ? "superAdmin" : staffRole === "Venue Manager" ? "venueManager" : staffRole === "Vendor Manager" ? "vendorManager" : "finance", locale)}</small></div></div>
      <nav className="admin-nav">{adminNav.filter(([, section]) => allowed.includes(section)).map(([href, key, Icon]) => <Link className={currentModule === key || (currentModule === "" && key === "dashboard") ? "active" : ""} key={href} href={href}><Icon size={17} aria-hidden="true" /><span>{t(moduleNames[key] || key, locale)}</span></Link>)}</nav>
    </aside>
    <div className="admin-content">{children}</div>
  </div>;
}

export function AdminWorkspace({ pathname }: { pathname: string }) {
  const { locale, staffRole } = useDemo();
  const pieces = pathname.split("/").filter(Boolean);
  const section = moduleForPath(pathname);
  const allowed = roleModules[staffRole] || roleModules["Super Admin"];
  if (pathname === "/admin/login") return <AdminLoginPreview />;
  if (!allowed.includes(section)) return <AdminFrame pathname={pathname}><section className="card access-denied"><LockKeyhole size={26} aria-hidden="true" /><h1>{t("accessDenied", locale)}</h1><p>{t("adminRoleDenied", locale)}</p><Link className="btn btn-primary" href="/demo">{t("demoMenu", locale)}</Link></section></AdminFrame>;
  let content: React.ReactNode;
  if (pathname === "/admin" || pathname === "/admin/") content = <AdminDashboard />;
  else if (pathname === "/admin/bookings") content = <AdminBookings />;
  else if (pieces[1] === "bookings" && pieces[2] && pieces[3] === "edit") content = <AdminBookingForm key={pieces[2]} bookingId={pieces[2]} />;
  else if (pieces[1] === "bookings" && pieces[2] === "new") content = <AdminBookingForm key="new-booking" />;
  else if (pieces[1] === "bookings" && pieces[2]) content = <AdminBookingDetail bookingId={pieces[2]} />;
  else if (pathname === "/admin/calendar") content = <AdminCalendarScreen />;
  else if (pathname === "/admin/venues") content = <AdminVenueList />;
  else if (pieces[1] === "venues" && pieces[2] === "new") content = <AdminVenueForm key="new-venue" />;
  else if (pieces[1] === "venues" && pieces[2] && pieces[3] === "packages") content = <AdminPackages venueId={pieces[2]} />;
  else if (pieces[1] === "venues" && pieces[2]) content = <AdminVenueForm key={pieces[2]} venueId={pieces[2]} />;
  else if (pathname === "/admin/vendors") content = <AdminVendorList />;
  else if (pieces[1] === "vendors" && pieces[2]) content = <AdminVendorDetail key={pieces[2]} vendorId={pieces[2]} />;
  else if (pathname === "/admin/categories") content = <AdminCategories />;
  else if (pathname === "/admin/customers") content = <AdminCustomerList />;
  else if (pieces[1] === "customers" && pieces[2]) content = <AdminCustomerDetail customerId={pieces[2]} />;
  else if (pathname === "/admin/inquiries") content = <AdminInquiryList />;
  else if (pieces[1] === "inquiries" && pieces[2]) content = <AdminInquiryDetail inquiryId={pieces[2]} />;
  else if (pathname === "/admin/payments") content = <AdminPaymentList />;
  else if (pieces[1] === "payments" && pieces[2]) content = <AdminPaymentDetail paymentId={pieces[2]} />;
  else if (pathname === "/admin/revenue") content = <AdminRevenueModel />;
  else if (pathname === "/admin/reports" || pieces[1] === "reports") content = <AdminReports />;
  else if (pathname === "/admin/users") content = <AdminUsers />;
  else if (pathname === "/admin/notifications") content = <AdminNotifications />;
  else if (pathname === "/admin/settings") content = <AdminSettings />;
  else if (pathname === "/admin/audit") content = <AdminAudit />;
  else if (pathname === "/admin/content") content = <AdminContent />;
  else content = <section className="card"><h1>{t("pageNotFound", locale)}</h1><Link className="btn btn-secondary" href="/admin">{t("back", locale)}</Link></section>;
  return <AdminFrame pathname={pathname}>{content}</AdminFrame>;
}

function AdminLoginPreview() {
  const { locale, setRole } = useDemo();
  const router = useRouter();
  const [status, setStatus] = useState<FormStatus>("idle");
  const [message, setMessage] = useState("");
  function enter() { setStatus("loading"); window.setTimeout(() => { setRole("admin"); setStatus("success"); setMessage(t("adminLoginSuccess", locale)); window.setTimeout(() => router.push("/admin"), 220); }, 180); }
  return <div className="admin-login-shell"><section className="card admin-login-card"><span className="admin-sidebar-mark" aria-hidden="true">A</span><p className="eyebrow">{t("admin", locale)} · {t("demoLabel", locale)}</p><h1>{t("adminLoginTitle", locale)}</h1><p>{t("adminLoginDescription", locale)}</p><div className="inline-notice"><ShieldAlert size={15} aria-hidden="true" />{t("accessNotice", locale)}</div><FormState status={status} locale={locale} message={message}><button type="button" className="btn btn-primary full-width" disabled={status === "loading"} onClick={enter}>{t("enterAdminPreview", locale)} <ArrowRight size={16} aria-hidden="true" /></button></FormState><Link className="text-link" href="/demo">{t("demoMenu", locale)}</Link></section></div>;
}

function PageTitle({ title, description, eyebrow }: { title: string; description?: string; eyebrow?: string }) {
  const { locale } = useDemo();
  return <header className="page-heading"><p className="eyebrow">{eyebrow || t("adminWorkspace", locale)}</p><h1>{title}</h1>{description && <p>{description}</p>}</header>;
}
function AdminDashboard() {
  const { locale, bookings, inquiries, venues, vendors, fees, auditLog, commissionMode, commissionValue, venueCommissionOverrides } = useDemo();
  const upcoming = bookings.filter((b) => b.eventDate >= todayISO() && b.status !== "Canceled").length;
  const commission = bookings.filter((b) => b.status === "Confirmed" || b.status === "Completed").reduce((sum, b) => {
    const override = venueCommissionOverrides[b.venueId];
    const value = override ?? commissionValue;
    return sum + (commissionMode === "percentage" ? b.total * value / 100 : value);
  }, 0);
  const leadFees = fees.filter((fee) => fee.status === "Paid").reduce((sum, fee) => sum + fee.amount, 0);
  const notificationKeys: Record<string, string> = { "NT-1": "notificationBooking", "NT-2": "notificationVendor", "NT-3": "notificationCalendar" };
  return <div className="page-stack"><PageTitle title={t("adminDashboard", locale)} description={t("adminOverviewText", locale)} /><DemoNotice />
    <section className="dashboard-hero" aria-label={t("upcomingEvents", locale)}><div className="dashboard-hero-figure"><span className="dashboard-hero-number">{formatNumber(upcoming, locale)}</span><span className="dashboard-hero-label">{t("upcomingEvents", locale)}</span></div></section>
    <div className="stats-grid admin-stat-grid"><StatCard title={t("totalBookings", locale)} value={formatNumber(bookings.length, locale)} icon={ClipboardList} /><StatCard title={t("upcomingEvents", locale)} value={formatNumber(upcoming, locale)} icon={CalendarDays} /><StatCard title={t("newInquiries", locale)} value={formatNumber(inquiries.filter((x) => x.status === "New").length, locale)} icon={Bell} /><StatCard title={t("activeVenues", locale)} value={formatNumber(venues.length, locale)} icon={Package} /><StatCard title={t("activeVendors", locale)} value={formatNumber(vendors.filter((x) => x.status === "Active").length, locale)} icon={Users} /><StatCard title={t("totalRevenue", locale)} value={formatETB(commission + leadFees, locale)} icon={CircleDollarSign} /></div>
    <section className="admin-status-counts" aria-labelledby="booking-status-counts"><h2 id="booking-status-counts">{t("bookingsByStatus", locale)}</h2><div className="status-count-grid">{(["Requested", "Reserved", "Confirmed", "Completed", "Canceled"] as const).map((status) => <article className="card status-count-card" key={status}><StatusBadge status={status} locale={locale} /><strong>{formatNumber(bookings.filter((booking) => booking.status === status).length, locale)}</strong></article>)}</div></section>
    <div className="admin-dashboard-columns"><section className="card"><div className="section-heading"><div><p className="eyebrow">{t("recentActivity", locale)}</p><h2>{t("auditLog", locale)}</h2></div><Link className="text-link" href="/admin/audit">{t("viewDetails", locale)} <ArrowRight size={14} aria-hidden="true" /></Link></div>{auditLog.length ? <ul className="admin-activity-list">{auditLog.slice(0, 5).map((record) => <li key={record.id}><strong>{t(record.action, locale)}</strong><span>{record.details}</span><small>{formatDate(record.at, locale)} · {staffRoleLabel(record.actor, locale)}</small></li>)}</ul> : <p className="muted">{t("noRecentActivity", locale)}</p>}</section><section className="card"><p className="eyebrow">{t("notifications", locale)}</p><div className="section-heading"><h2>{t("notificationCenter", locale)}</h2><Link className="text-link" href="/admin/notifications">{t("viewDetails", locale)} <ArrowRight size={14} aria-hidden="true" /></Link></div><ListState locale={locale} items={mockNotifications.length} loading={false} emptyKey="noNotifications"><ul className="admin-activity-list">{mockNotifications.map((item) => <li key={item.id}><strong>{t(notificationKeys[item.id], locale)}</strong><span>{t(`${notificationKeys[item.id]}Detail`, locale)}</span><small>{formatDate(item.date, locale)}</small></li>)}</ul></ListState></section></div>
  </div>;
}
function StatCard({ title, value, icon: Icon }: { title: string; value: string; icon: LucideIcon }) { return <article className="card stat-card"><span>{title}</span><strong>{value}</strong><Icon aria-hidden="true" /></article>; }

function AdminCalendarScreen() {
  const { locale, bookings, venues } = useDemo();
  const [venueId, setVenueId] = useState("");
  const [month, setMonth] = useState(() => new Date(new Date().getFullYear(), new Date().getMonth(), 1));
  const items = bookings.filter((booking) => !venueId || booking.venueId === venueId).sort((a, b) => a.eventDate.localeCompare(b.eventDate));
  const monthItems = items.filter((booking) => { const date = new Date(`${booking.eventDate}T12:00:00`); return date.getFullYear() === month.getFullYear() && date.getMonth() === month.getMonth(); });
  const held = items.filter((booking) => booking.status === "Reserved" || booking.status === "Confirmed");
  const overlaps = items.filter((booking) => booking.status === "Requested" && held.some((other) => other.venueId === booking.venueId && other.eventDate === booking.eventDate));
  const firstDay = new Date(month.getFullYear(), month.getMonth(), 1).getDay();
  const days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate();
  const cells = [...Array(firstDay).fill(null), ...Array.from({ length: days }, (_, index) => index + 1)];
  const monthLabel = formatMonthYear(month, locale);
  const weekdays = ["weekdaySun", "weekdayMon", "weekdayTue", "weekdayWed", "weekdayThu", "weekdayFri", "weekdaySat"].map((key) => t(key, locale));
  function bookingsOn(day: number) { const date = `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`; return monthItems.filter((booking) => booking.eventDate === date); }
  return <div className="page-stack"><PageTitle title={t("calendarOverview", locale)} description={t("calendarAgenda", locale)} />
    <div className="card calendar-toolbar"><label className="label" htmlFor="admin-calendar-venue">{t("venue", locale)}</label><select id="admin-calendar-venue" className="field" value={venueId} onChange={(event) => setVenueId(event.target.value)}><option value="">{t("all", locale)} {t("venues", locale)}</option>{venues.map((venue, index) => <option key={`${venue.id}-${index}`} value={venue.id}>{venue.name}</option>)}</select><div className="month-controls"><button type="button" className="btn btn-secondary" aria-label={t("previousMonth", locale)} onClick={() => setMonth((value) => new Date(value.getFullYear(), value.getMonth() - 1, 1))}><ChevronLeft size={16} aria-hidden="true" />{t("previousMonth", locale)}</button><strong aria-live="polite">{monthLabel}</strong><button type="button" className="btn btn-secondary" aria-label={t("nextMonth", locale)} onClick={() => setMonth((value) => new Date(value.getFullYear(), value.getMonth() + 1, 1))}>{t("nextMonth", locale)}<ChevronRight size={16} aria-hidden="true" /></button></div></div>
    {overlaps.length > 0 && <div className="conflict-alert" role="alert"><ShieldAlert size={18} aria-hidden="true" /><div><strong>{t("conflictWarning", locale)}</strong><p>{formatNumber(overlaps.length, locale)} {t("overlapFlag", locale)}. {t("noAutoChange", locale)}</p></div></div>}
    <div className="admin-month-view" aria-label={`${t("calendarOverview", locale)}: ${monthLabel}`}><div className="month-grid">{weekdays.map((day) => <div className="month-weekday" key={day}>{day}</div>)}{cells.map((day, index) => <div key={`${day || "blank"}-${index}`} className={`month-cell ${day ? "" : "is-blank"}`}>{day && <><strong className="month-day-number">{formatNumber(day, locale)}</strong>{bookingsOn(day).slice(0, 3).map((booking) => <Link className="month-event" key={booking.id} href={`/admin/bookings/${booking.id}`}><StatusBadge status={booking.status} locale={locale} /><span>{venues.find((venue) => venue.id === booking.venueId)?.name || booking.customer}</span></Link>)}{bookingsOn(day).length > 3 && <span className="small-note">+{formatNumber(bookingsOn(day).length - 3, locale)}</span>}</>}</div>)}</div></div>
    <section className="admin-calendar-agenda"><h2>{t("calendarAgenda", locale)}</h2><ListState locale={locale} items={monthItems.length} loading={false} noResults={Boolean(venueId)} emptyKey="noBookings"><div className="agenda-list">{monthItems.map((booking) => <AgendaBooking key={booking.id} booking={booking} />)}</div></ListState></section>
  </div>;
}
function AgendaBooking({ booking }: { booking: Booking }) { const { locale, venues, bookings } = useDemo(); const venue = venues.find((item) => item.id === booking.venueId); const hasConflict = booking.status === "Requested" && bookings.some((item) => item.id !== booking.id && item.venueId === booking.venueId && item.eventDate === booking.eventDate && (item.status === "Reserved" || item.status === "Confirmed")); return <article className={`agenda-item ${hasConflict ? "has-conflict" : ""}`}><div className="agenda-date"><strong>{formatDate(booking.eventDate, locale)}</strong><span>{formatNumber(booking.guests, locale)} {t("guests", locale)}</span></div><div className="agenda-body"><h3>{venue?.name} · {booking.customer}</h3><StatusBadge status={booking.status} locale={locale} />{hasConflict && <StatusBadge status="Needs reschedule or reject" locale={locale} />}<p>{booking.packageName} · {formatETB(booking.total, locale)}</p></div><Link className="btn btn-secondary" href={`/admin/bookings/${booking.id}`}>{t("viewDetails", locale)}</Link></article>; }

function AdminBookingForm({ bookingId }: { bookingId?: string }) {
  const demo = useDemo(); const { locale } = demo; const router = useRouter();
  const current = demo.bookings.find((booking) => booking.id === bookingId);
  const [venueId, setVenueId] = useState(current?.venueId || demo.venues[0]?.id || ""); const [customer, setCustomer] = useState(current?.customer || "");
  const [eventDate, setEventDate] = useState(current?.eventDate || ""); const [guests, setGuests] = useState(current?.guests ? String(current.guests) : "");
  const [packageName, setPackageName] = useState(current?.packageName || ""); const [notes, setNotes] = useState(current?.notes || ""); const [bookingStatus, setBookingStatus] = useState<Booking["status"]>(current?.status || "Requested");
  const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); const [errors, setErrors] = useState<Record<string, string>>({});
  const venue = demo.venues.find((item) => item.id === venueId); const packages = venue?.packages || [];
  function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const next: Record<string, string> = {}; const count = Number(guests); if (!customer.trim()) next.customer = t("nameRequired", locale); if (!eventDate || eventDate < todayISO()) next.date = t("dateRequired", locale); if (!count || count < 1 || (venue && count > venue.capacity)) next.guests = t("numberError", locale); if (!venue) next.venue = t("chooseVenue", locale); if (!packageName) next.packageName = t("packageRequired", locale); setErrors(next); if (Object.keys(next).length) { setStatus("error"); setMessage(t("errorKeep", locale)); return; } setStatus("loading"); setMessage(""); window.setTimeout(() => { const selectedPackage = packages.find((item) => item.name === packageName) || packages[0]; if (!selectedPackage || !venue) { setStatus("error"); setMessage(t("actionFailed", locale)); return; } if (current) demo.updateBooking({ ...current, venueId, customer: customer.trim(), eventDate, guests: count, packageName, total: selectedPackage.price, deposit: Math.round(selectedPackage.price * .25), notes, status: bookingStatus }); else { const created = demo.createBooking({ venueId, customer: customer.trim(), eventDate, guests: count, packageName, total: selectedPackage.price, deposit: Math.round(selectedPackage.price * .25), notes, source: "Manual" }); demo.setBookingStatus(created.id, bookingStatus); demo.addAuditRecord("auditManualBookingCreated", `${created.id} · ${customer.trim()}`); } setStatus("success"); setMessage(t("actionSaved", locale)); }, 280); }
  return <div className="page-stack"><PageTitle title={t(current ? "editBookingTitle" : "newBookingTitle", locale)} description={t("manualBookingHelp", locale)} /><FormState status={status} locale={locale} message={message}><form className="card form-card admin-form-grid" onSubmit={submit} noValidate>
    <Field label={t("customerName", locale)} id="admin-booking-customer" value={customer} error={errors.customer} onChange={setCustomer} />
    <div><label className="label" htmlFor="admin-booking-venue">{t("venue", locale)} *</label><select id="admin-booking-venue" className={`field ${errors.venue ? "field-error" : ""}`} value={venueId} onChange={(event) => { setVenueId(event.target.value); const selected = demo.venues.find((item) => item.id === event.target.value); setPackageName(selected?.packages[0]?.name || ""); }}><option value="">{t("chooseVenue", locale)}</option>{demo.venues.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>{errors.venue && <p className="field-error-text">{errors.venue}</p>}</div>
    <Field label={t("eventDateLabel", locale)} id="admin-booking-date" type="date" value={eventDate} error={errors.date} onChange={setEventDate} min={todayISO()} />
    <Field label={t("guestLabel", locale)} id="admin-booking-guests" type="number" value={guests} error={errors.guests} onChange={setGuests} min="1" max={venue?.capacity} />
    <div><label className="label" htmlFor="admin-booking-package">{t("package", locale)} *</label><select id="admin-booking-package" className={`field ${errors.packageName ? "field-error" : ""}`} value={packageName} onChange={(event) => setPackageName(event.target.value)}><option value="">{t("choosePackage", locale)}</option>{packages.map((item) => <option key={item.name} value={item.name}>{item.name} · {formatETB(item.price, locale)}</option>)}</select>{errors.packageName && <p className="field-error-text">{errors.packageName}</p>}</div>
    <div><label className="label" htmlFor="admin-booking-status">{t("status", locale)}</label><select id="admin-booking-status" className="field" value={bookingStatus} onChange={(event) => setBookingStatus(event.target.value as Booking["status"])}>{(["Requested", "Reserved", "Confirmed", "Completed", "Canceled"] as const).map((value) => <option key={value} value={value}>{t(value.toLowerCase(), locale)}</option>)}</select></div>
    <div className="admin-form-full"><label className="label" htmlFor="admin-booking-notes">{t("notes", locale)}</label><textarea id="admin-booking-notes" className="field textarea" value={notes} onChange={(event) => setNotes(event.target.value)} /></div>
    <div className="admin-form-full"><p className="small-note">{t("source", locale)}: <strong>{current ? t(current.source.toLowerCase(), locale) : t("manual", locale)}</strong></p><div className="form-actions"><Link href={current ? `/admin/bookings/${current.id}` : "/admin/bookings"} className="btn btn-secondary">{t("cancel", locale)}</Link><button type="submit" className="btn btn-primary" disabled={status === "loading"}>{t("saveChanges", locale)}</button></div>{status === "success" && <Link className="text-link" href="/admin/bookings">{t("bookingTable", locale)} <ArrowRight size={14} aria-hidden="true" /></Link>}</div>
  </form></FormState></div>;
}
function Field({ label, id, value, onChange, error, type = "text", min, max }: { label: string; id: string; value: string; onChange: (value: string) => void; error?: string; type?: string; min?: string; max?: number }) { return <div><label className="label" htmlFor={id}>{label} *</label><input id={id} className={`field ${error ? "field-error" : ""}`} type={type} value={value} onChange={(event) => onChange(event.target.value)} aria-invalid={!!error} aria-describedby={error ? `${id}-error` : undefined} min={min} max={max} />{error && <p className="field-error-text" id={`${id}-error`}>{error}</p>}</div>; }

function AdminVenueList() { const { locale, venues } = useDemo(); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = venues.filter((venue) => `${venue.name} ${venue.area} ${venue.type}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("venuesAdmin", locale)} description={t("venueManagementHelp", locale)} /><div className="admin-list-toolbar"><label className="sr-only" htmlFor="venue-admin-search">{t("searchRecords", locale)}</label><input id="venue-admin-search" className="field" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("searchPlaceholder", locale)} /><Link className="btn btn-primary" href="/admin/venues/new">{t("newVenue", locale)}</Link></div><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query} emptyKey="emptyVenues"><div className="admin-record-list">{filtered.map((venue, index) => <article className="card admin-record" key={`${venue.id}-${index}`}><div><p className="eyebrow">{venueTypeLabel(venue.type, locale)} · {venue.area}</p><h2>{venue.name}</h2><p className="muted">{formatNumber(venue.capacity, locale)} {t("guests", locale)} · {formatETB(venue.price, locale)} {t("startingAt", locale)}</p><p className="small-note">{formatNumber(venue.packages.length, locale)} {t("packages", locale)} · {venue.amenities.join(" · ")}</p></div><div className="admin-record-actions"><Link className="btn btn-secondary" href={`/admin/venues/${venue.id}`}>{t("editVenue", locale)}</Link><Link className="btn btn-quiet" href={`/admin/venues/${venue.id}/packages`}>{t("venuePackages", locale)}</Link></div></article>)}</div></ListState></div>; }
function useLoading() { const [loading, setLoading] = useState(true); useEffect(() => { const timer = window.setTimeout(() => setLoading(false), 180); return () => window.clearTimeout(timer); }, []); return loading; }
function AdminVenueForm({ venueId }: { venueId?: string }) {
  const demo = useDemo();
  const { locale } = demo;
  const current = demo.venues.find((item) => item.id === venueId);
  const [name, setName] = useState(current?.name || "");
  const [type, setType] = useState(current?.type || "Wedding hall");
  const [area, setArea] = useState(current?.area || "Bole");
  const [capacity, setCapacity] = useState(String(current?.capacity || ""));
  const [price, setPrice] = useState(String(current?.price || ""));
  const [description, setDescription] = useState(current?.description || "");
  const [amenities, setAmenities] = useState(current?.amenities.join(", ") || "");
  const [mapLink, setMapLink] = useState(current?.mapLink || "");
  const [contact, setContact] = useState(current?.contact || "");
  const [policies, setPolicies] = useState(current?.policies || "");
  const [photos, setPhotos] = useState((current?.photos || []).join("\n"));
  const [videos, setVideos] = useState((current?.videos || []).join("\n"));
  const [status, setStatus] = useState<FormStatus>("idle");
  const [message, setMessage] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});
  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const next: Record<string, string> = {};
    if (!name.trim()) next.name = t("nameRequired", locale);
    if (!area.trim()) next.area = t("required", locale);
    if (Number(capacity) < 1 || !Number.isFinite(Number(capacity))) next.capacity = t("numberError", locale);
    if (price.trim() === "" || !Number.isFinite(Number(price)) || Number(price) < 0) next.price = t("numberError", locale);
    if (!description.trim()) next.description = t("messageRequired", locale);
    setErrors(next);
    if (Object.keys(next).length) { setStatus("error"); setMessage(t("errorKeep", locale)); return; }
    setStatus("loading"); setMessage("");
    window.setTimeout(() => {
      const venue: Venue = {
        id: current?.id || `venue-${Date.now()}`, name: name.trim(), type, area: area.trim(),
        capacity: Number(capacity), price: Number(price), description: description.trim(),
        amenities: amenities.split(",").map((item) => item.trim()).filter(Boolean),
        packages: current?.packages || [{ name: "Essential", price: Number(price), description: t("basicPackage", locale) }, { name: "Gather", price: Number(price) * 1.4, description: t("standardPackage", locale) }, { name: "Full celebration", price: Number(price) * 1.9, description: t("premiumPackage", locale) }],
        rating: current?.rating || 4.5, imageLabel: current?.imageLabel || `${area} event space`, mapLink: mapLink.trim(),
        policies: policies.trim(), photos: photos.split("\n").map((item) => item.trim()).filter(Boolean), videos: videos.split("\n").map((item) => item.trim()).filter(Boolean), contact: contact.trim(),
      };
      demo.saveVenue(venue); setStatus("success"); setMessage(t("actionSaved", locale));
    }, 240);
  }
  return <div className="page-stack">
    <PageTitle title={t(current ? "editVenue" : "newVenue", locale)} description={t("venueManagementHelp", locale)} />
    <FormState status={status} locale={locale} message={message}>
      <form className="card form-card admin-form-grid" onSubmit={submit} noValidate>
        <Field label={t("venueName", locale)} id="venue-name" value={name} onChange={setName} error={errors.name} />
        <div><label className="label" htmlFor="venue-type">{t("type", locale)}</label><select id="venue-type" className="field" value={type} onChange={(event) => setType(event.target.value)}>{["Wedding hall", "Garden venue", "Conference space", "Hotel ballroom"].map((value) => <option key={value} value={value}>{venueTypeLabel(value, locale)}</option>)}</select></div>
        <Field label={t("area", locale)} id="venue-area" value={area} onChange={setArea} error={errors.area} />
        <Field label={t("capacity", locale)} id="venue-capacity" type="number" value={capacity} onChange={setCapacity} error={errors.capacity} min="1" />
        <Field label={t("startingPriceLabel", locale)} id="venue-price" type="number" value={price} onChange={setPrice} error={errors.price} min="0" />
        <div className="admin-form-full"><label className="label" htmlFor="venue-description">{t("descriptionLabel", locale)}</label><textarea id="venue-description" className={`field textarea ${errors.description ? "field-error" : ""}`} value={description} onChange={(event) => setDescription(event.target.value)} aria-invalid={!!errors.description} />{errors.description && <p className="field-error-text">{errors.description}</p>}</div>
        <div className="admin-form-full"><label className="label" htmlFor="venue-amenities">{t("adminAmenities", locale)}</label><input id="venue-amenities" className="field" value={amenities} onChange={(event) => setAmenities(event.target.value)} /></div>
        <div><label className="label" htmlFor="venue-map-link">{t("adminMapLink", locale)}</label><input id="venue-map-link" className="field" value={mapLink} onChange={(event) => setMapLink(event.target.value)} /></div><div><label className="label" htmlFor="venue-contact">{t("adminContact", locale)}</label><input id="venue-contact" className="field" value={contact} onChange={(event) => setContact(event.target.value)} /></div>
        <div className="admin-form-full"><label className="label" htmlFor="venue-policies">{t("adminPolicies", locale)}</label><textarea id="venue-policies" className="field textarea" value={policies} onChange={(event) => setPolicies(event.target.value)} /></div>
        <div><label className="label" htmlFor="venue-photos">{t("adminPhotos", locale)}</label><textarea id="venue-photos" className="field textarea" value={photos} onChange={(event) => setPhotos(event.target.value)} /><p className="small-note">{t("galleryLinksHelp", locale)}</p></div>
        <div><label className="label" htmlFor="venue-videos">{t("adminVideos", locale)}</label><textarea id="venue-videos" className="field textarea" value={videos} onChange={(event) => setVideos(event.target.value)} /><p className="small-note">{t("galleryLinksHelp", locale)}</p></div>
        <div className="admin-form-full"><div className="inline-notice">{t("sampleGalleryNote", locale)}</div><div className="form-actions"><Link href="/admin/calendar" className="btn btn-secondary">{t("manageAvailability", locale)}</Link><Link href="/admin/venues" className="btn btn-secondary">{t("cancel", locale)}</Link><button type="submit" className="btn btn-primary" disabled={status === "loading"}>{t("saveChanges", locale)}</button></div>{status === "success" && <div className="form-actions">{current && <Link className="btn btn-secondary" href={`/admin/venues/${current.id}/packages`}>{t("venuePackages", locale)}</Link>}<Link className="text-link" href="/admin/venues">{t("venuesAdmin", locale)}</Link></div>}</div>
      </form>
    </FormState>
  </div>;
}

function AdminPackages({ venueId }: { venueId: string }) { const demo = useDemo(); const { locale } = demo; const venue = demo.venues.find((item) => item.id === venueId); const [packages, setPackages] = useState(venue?.packages || []); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); if (!venue) return <section className="card"><h1>{t("notFound", locale)}</h1><Link href="/admin/venues">{t("venuesAdmin", locale)}</Link></section>; const currentVenue = venue; function save(event: React.FormEvent) { event.preventDefault(); if (packages.some((item) => !item.name.trim() || item.price < 0)) { setStatus("error"); setMessage(t("errorKeep", locale)); return; } setStatus("loading"); window.setTimeout(() => { demo.saveVenue({ ...currentVenue, packages }); setStatus("success"); setMessage(t("actionSaved", locale)); }, 200); } return <div className="page-stack"><PageTitle title={`${t("venuePackages", locale)} · ${venue.name}`} description={t("packageManagerHelp", locale)} /><FormState status={status} locale={locale} message={message}><form className="card form-card" onSubmit={save}>{packages.map((item, index) => <div className="package-edit-row" key={`${item.name}-${index}`}><label className="label" htmlFor={`package-name-${index}`}>{t("packageName", locale)}</label><input id={`package-name-${index}`} className="field" value={item.name} onChange={(event) => setPackages((rows) => rows.map((row, i) => i === index ? { ...row, name: event.target.value } : row))} /><label className="label" htmlFor={`package-price-${index}`}>{t("price", locale)}</label><input id={`package-price-${index}`} type="number" min="0" className="field" value={item.price} onChange={(event) => setPackages((rows) => rows.map((row, i) => i === index ? { ...row, price: Number(event.target.value) } : row))} /><label className="label" htmlFor={`package-desc-${index}`}>{t("description", locale)}</label><input id={`package-desc-${index}`} className="field" value={item.description} onChange={(event) => setPackages((rows) => rows.map((row, i) => i === index ? { ...row, description: event.target.value } : row))} /></div>)}<div className="form-actions"><button type="button" className="btn btn-secondary" onClick={() => setPackages((rows) => [...rows, { name: "", price: 0, description: "" }])}>{t("addPackage", locale)}</button><button type="submit" className="btn btn-primary" disabled={status === "loading"}>{t("saveChanges", locale)}</button></div></form></FormState></div>; }

function AdminVendorList() { const { locale, vendors } = useDemo(); const [filter, setFilter] = useState(""); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = vendors.filter((vendor) => (!filter || vendor.status === filter) && `${vendor.name} ${vendor.area} ${vendor.category}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("vendorsAdmin", locale)} description={t("vendorModerationHelp", locale)} /><div className="admin-list-toolbar"><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={query} onChange={(event) => setQuery(event.target.value)} /><select className="field" aria-label={t("vendorStatus", locale)} value={filter} onChange={(event) => setFilter(event.target.value)}><option value="">{t("allStatuses", locale)}</option>{["Pending", "Active", "Suspended"].map((value) => <option key={value} value={value}>{t(value.toLowerCase(), locale)}</option>)}</select></div><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query || !!filter} emptyKey="emptyVendors"><div className="admin-record-list">{filtered.map((vendor) => <article className="card admin-record" key={vendor.id}><div><p className="eyebrow">{categoryLabel(vendor.category, locale)} · {vendor.area}</p><h2>{vendor.name}</h2><p className="muted">{vendor.description}</p><p>{formatETB(vendor.startingPrice, locale)} · {vendor.services.join(" · ")}</p></div><div className="admin-record-actions"><StatusBadge status={vendor.status} locale={locale} />{vendor.applicationStatus && <StatusBadge status={vendor.applicationStatus} locale={locale} />}<Link className="btn btn-secondary" href={`/admin/vendors/${vendor.id}`}>{t("reviewApplication", locale)}</Link></div></article>)}</div></ListState></div>; }
function AdminVendorDetail({ vendorId }: { vendorId: string }) { const demo = useDemo(); const { locale } = demo; const router = useRouter(); const vendor = demo.vendors.find((item) => item.id === vendorId); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); if (!vendor) return <section className="card"><h1>{t("notFound", locale)}</h1><Link href="/admin/vendors">{t("vendorsAdmin", locale)}</Link></section>; const currentVendor = vendor; function update(nextStatus: VendorStatus, applicationStatus: Vendor["applicationStatus"] = currentVendor.applicationStatus) { const updated = { ...currentVendor, status: nextStatus, applicationStatus }; demo.saveVendor(updated); setStatus("success"); setMessage(t("actionSaved", locale)); } function remove() { setStatus("loading"); setTimeout(() => { demo.removeVendor(currentVendor.id); router.push("/admin/vendors"); }, 220); } return <div className="page-stack"><div className="breadcrumbs"><Link href="/admin/vendors">{t("vendorsAdmin", locale)}</Link><span>/</span><span>{vendor.name}</span></div><PageTitle title={t("vendorDetails", locale)} description={t("vendorModerationHelp", locale)} /><FormState status={status} locale={locale} message={message}><section className="card vendor-admin-detail"><div className="card-title-row"><div><p className="eyebrow">{categoryLabel(vendor.category, locale)} · {vendor.area}</p><h2>{vendor.name}</h2></div><div className="admin-status-group"><StatusBadge status={vendor.status} locale={locale} />{vendor.applicationStatus && <StatusBadge status={vendor.applicationStatus} locale={locale} />}</div></div><p>{vendor.description}</p><p>{vendor.services.join(" · ")} · {formatETB(vendor.startingPrice, locale)}</p><div className="inline-notice"><ShieldAlert size={15} aria-hidden="true" />{t("applicationReviewNotice", locale)}</div><div className="form-actions">{vendor.status !== "Active" && <button type="button" className="btn btn-primary" onClick={() => update("Active", "Approved")}>{t("approveApplication", locale)}</button>}{vendor.applicationStatus !== "Needs changes" && <button type="button" className="btn btn-secondary" onClick={() => update("Pending", "Needs changes")}>{t("requestChanges", locale)}</button>}{vendor.applicationStatus !== "Rejected" && <button type="button" className="btn btn-danger" onClick={() => update("Suspended", "Rejected")}>{t("rejectApplication", locale)}</button>}{vendor.status === "Active" && <button type="button" className="btn btn-danger" onClick={() => update("Suspended", vendor.applicationStatus)}>{t("suspendVendor", locale)}</button>}<button type="button" className="btn btn-danger" onClick={remove} disabled={status === "loading"}>{t("removeVendor", locale)}</button></div><VendorListingEditor vendor={vendor} /></section></FormState></div>; }
function VendorListingEditor({ vendor }: { vendor: Vendor }) { const demo = useDemo(); const { locale } = demo; const [name, setName] = useState(vendor.name); const [description, setDescription] = useState(vendor.description); const [price, setPrice] = useState(String(vendor.startingPrice)); const [area, setArea] = useState(vendor.area); const [category, setCategory] = useState(vendor.category); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); return <div className="vendor-listing-editor"><h3>{t("listingEditor", locale)}</h3><FormState status={status} locale={locale} message={message}><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); if (!name.trim() || !Number(price) || !area.trim()) { setStatus("error"); setMessage(t("errorKeep", locale)); return; } setStatus("loading"); window.setTimeout(() => { demo.saveVendor({ ...vendor, name: name.trim(), description: description.trim(), startingPrice: Number(price), area: area.trim(), category }); setStatus("success"); setMessage(t("actionSaved", locale)); }, 220); }}><Field label={t("businessName", locale)} id="vendor-business-name" value={name} onChange={setName} /><div><label className="label" htmlFor="vendor-category">{t("category", locale)}</label><select id="vendor-category" className="field" value={category} onChange={(event) => setCategory(event.target.value)}>{demo.categories.map((item) => <option key={item}>{item}</option>)}</select></div><Field label={t("area", locale)} id="vendor-area" value={area} onChange={setArea} /><Field label={t("startingPriceLabel", locale)} id="vendor-start-price" type="number" value={price} onChange={setPrice} min="0" /><div className="admin-form-full"><label className="label" htmlFor="vendor-description">{t("descriptionLabel", locale)}</label><textarea id="vendor-description" className="field textarea" value={description} onChange={(event) => setDescription(event.target.value)} /></div><div className="admin-form-full"><button className="btn btn-secondary" type="submit" disabled={status === "loading"}>{t("saveChanges", locale)}</button></div></form></FormState></div>; }
function AdminCategories() { const demo = useDemo(); const { locale } = demo; const [value, setValue] = useState(""); const [editing, setEditing] = useState(""); const [query, setQuery] = useState(""); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); const filtered = demo.categories.filter((item) => item.toLowerCase().includes(query.toLowerCase())); const loading = useLoading(); function save(event: React.FormEvent) { event.preventDefault(); if (!value.trim()) { setStatus("error"); setMessage(t("nameRequired", locale)); return; } const next = editing ? demo.categories.map((item) => item === editing ? value.trim() : item) : [...demo.categories, value.trim()]; if (!editing && demo.categories.some((item) => item.toLowerCase() === value.trim().toLowerCase())) { setStatus("error"); setMessage(t("duplicateCategory", locale)); return; } setStatus("loading"); setTimeout(() => { demo.saveCategories(next); setValue(""); setEditing(""); setStatus("success"); setMessage(t("actionSaved", locale)); }, 180); } return <div className="page-stack"><PageTitle title={t("categories", locale)} description={t("categoryManagerHelp", locale)} /><FormState status={status} locale={locale} message={message}><form className="card admin-inline-form" onSubmit={save}><label className="label" htmlFor="category-name">{t("category", locale)}</label><input id="category-name" className="field" value={value} onChange={(event) => setValue(event.target.value)} /><button type="submit" className="btn btn-primary" disabled={status === "loading"}>{editing ? t("saveChanges", locale) : t("createCategory", locale)}</button>{editing && <button type="button" className="btn btn-secondary" onClick={() => { setEditing(""); setValue(""); }}>{t("cancel", locale)}</button>}</form></FormState><label className="label" htmlFor="category-search">{t("search", locale)}</label><input id="category-search" className="field" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("searchPlaceholder", locale)} /><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query} emptyKey="noCategories"><div className="admin-record-list">{filtered.map((item) => <article className="card admin-record" key={item}><h2>{categoryLabel(item, locale)}</h2><div className="admin-record-actions"><button className="btn btn-secondary" type="button" onClick={() => { setEditing(item); setValue(item); }}>{t("edit", locale)}</button><button className="btn btn-danger" type="button" onClick={() => demo.saveCategories(demo.categories.filter((category) => category !== item))}>{t("remove", locale)}</button></div></article>)}</div></ListState></div>; }

function AdminCustomerList() { const { locale, customers } = useDemo(); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = customers.filter((customer) => `${customer.name} ${customer.phone}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("customersAdmin", locale)} description={t("customerManagementHelp", locale)} /><div className="admin-list-toolbar"><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={query} onChange={(event) => setQuery(event.target.value)} /></div><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query} emptyKey="noCustomers"><div className="admin-record-list">{filtered.map((customer) => <article className="card admin-record" key={customer.id}><div><p className="eyebrow">{customer.id}</p><h2>{customer.name}</h2><p className="muted">{customer.phone}</p></div><Link className="btn btn-secondary" href={`/admin/customers/${customer.id}`}>{t("viewDetails", locale)}</Link></article>)}</div></ListState></div>; }
function AdminCustomerDetail({ customerId }: { customerId: string }) {
  const { locale, customers, bookings, inquiries, payments } = useDemo();
  const loading = useLoading();
  const [bookingQuery, setBookingQuery] = useState("");
  const [inquiryQuery, setInquiryQuery] = useState("");
  const customer = customers.find((item) => item.id === customerId);
  if (!customer) return <section className="card"><h1>{t("notFound", locale)}</h1><Link href="/admin/customers">{t("customersAdmin", locale)}</Link></section>;

  const allCustomerBookings = bookings.filter((item) => item.customer === customer.name);
  const customerBookings = allCustomerBookings.filter((item) => `${item.id} ${item.eventDate} ${item.status}`.toLowerCase().includes(bookingQuery.trim().toLowerCase()));
  const customerInquiries = inquiries.filter((item) => item.customer === customer.name && `${item.id} ${item.eventDate} ${item.status} ${item.detail}`.toLowerCase().includes(inquiryQuery.trim().toLowerCase()));
  const customerPaymentCount = payments.filter((payment) => allCustomerBookings.some((booking) => booking.id === payment.bookingId)).length;

  return <div className="page-stack">
    <PageTitle title={customer.name} description={t("customerDetails", locale)} />
    <section className="card">
      <p>{customer.phone}</p>
      <section className="customer-related-list">
        <h2>{t("bookings", locale)} · {formatNumber(customerBookings.length, locale)}</h2>
        <label className="sr-only" htmlFor="customer-bookings-search">{t("searchRecords", locale)}</label>
        <input id="customer-bookings-search" className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={bookingQuery} onChange={(event) => setBookingQuery(event.target.value)} />
        <ListState locale={locale} items={customerBookings.length} loading={loading} noResults={Boolean(bookingQuery.trim())} emptyKey="noBookings">
          <ul className="admin-activity-list">{customerBookings.map((booking) => <li key={booking.id}><strong><Link href={`/admin/bookings/${booking.id}`}>{booking.id}</Link></strong><span>{formatDate(booking.eventDate, locale)}</span><StatusBadge status={booking.status} locale={locale} /></li>)}</ul>
        </ListState>
      </section>
      <section className="customer-related-list">
        <h2>{t("inquiries", locale)} · {formatNumber(customerInquiries.length, locale)}</h2>
        <label className="sr-only" htmlFor="customer-inquiries-search">{t("searchRecords", locale)}</label>
        <input id="customer-inquiries-search" className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={inquiryQuery} onChange={(event) => setInquiryQuery(event.target.value)} />
        <ListState locale={locale} items={customerInquiries.length} loading={loading} noResults={Boolean(inquiryQuery.trim())} emptyKey="noInquiries">
          <ul className="admin-activity-list">{customerInquiries.map((item) => <li key={item.id}><strong><Link href={`/admin/inquiries/${item.id}`}>{item.id}</Link></strong><span>{formatDate(item.eventDate, locale)}</span><StatusBadge status={item.status} locale={locale} /></li>)}</ul>
        </ListState>
      </section>
      <p>{t("payments", locale)} · {formatNumber(customerPaymentCount, locale)}</p>
    </section>
  </div>;
}
function AdminInquiryList() { const { locale, inquiries, vendors } = useDemo(); const [statusFilter, setStatusFilter] = useState(""); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = inquiries.filter((item) => (!statusFilter || item.status === statusFilter) && `${item.customer} ${item.detail} ${vendors.find((vendor) => vendor.id === item.vendorId)?.name || ""}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("inquiryAdmin", locale)} description={t("inquiryManagementHelp", locale)} /><div className="admin-list-toolbar"><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={query} onChange={(event) => setQuery(event.target.value)} /><select className="field" aria-label={t("status", locale)} value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="">{t("allStatuses", locale)}</option>{["New", "Responded", "Confirmed", "Declined"].map((value) => <option key={value} value={value}>{t(value.toLowerCase(), locale)}</option>)}</select></div><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query || !!statusFilter} emptyKey="noInquiries"><div className="admin-record-list">{filtered.map((item) => <article className="card admin-record" key={item.id}><div><p className="eyebrow">{formatDate(item.eventDate, locale)} · {vendors.find((vendor) => vendor.id === item.vendorId)?.name}</p><h2>{item.customer}</h2><p className="muted">{item.detail}</p></div><div className="admin-record-actions"><StatusBadge status={item.status} locale={locale} /><Link className="btn btn-secondary" href={`/admin/inquiries/${item.id}`}>{t("viewDetails", locale)}</Link></div></article>)}</div></ListState></div>; }
function AdminInquiryDetail({ inquiryId }: { inquiryId: string }) { const demo = useDemo(); const { locale } = demo; const inquiry = demo.inquiries.find((item) => item.id === inquiryId); const [reply, setReply] = useState(inquiry?.response || ""); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); const [error, setError] = useState(""); if (!inquiry) return <section className="card"><h1>{t("notFound", locale)}</h1><Link href="/admin/inquiries">{t("inquiryAdmin", locale)}</Link></section>; const current = inquiry; const vendor = demo.vendors.find((item) => item.id === current.vendorId); function save(next: "Responded" | "Confirmed" | "Declined") { if (next !== "Declined" && !reply.trim()) { setStatus("error"); setError(t("responseRequired", locale)); setMessage(t("errorKeep", locale)); return; } setError(""); setStatus("loading"); setTimeout(() => { demo.setInquiryStatus(current.id, next, reply.trim() || undefined, "admin"); demo.addAuditRecord("auditInquiryUpdatedAdmin", `${current.id} · ${next}`); setStatus("success"); setMessage(t("actionSaved", locale)); }, 220); } return <div className="page-stack"><PageTitle title={`${t("inquiryDetail", locale)} · ${inquiry.id}`} description={vendor?.name} /><section className="card"><div className="card-title-row"><h2>{inquiry.customer}</h2><StatusBadge status={inquiry.status} locale={locale} /></div><p>{formatDate(inquiry.eventDate, locale)} · {inquiry.detail}</p>{inquiry.response && <div className="response-box"><h3>{t("vendorResponse", locale)}</h3><p>{inquiry.response}</p></div>}<FormState status={status} locale={locale} message={message}><div className="response-form"><label className="label" htmlFor="admin-inquiry-reply">{t("response", locale)}</label><textarea id="admin-inquiry-reply" className={`field textarea ${error ? "field-error" : ""}`} value={reply} onChange={(event) => setReply(event.target.value)} aria-invalid={!!error} />{error && <p className="field-error-text">{error}</p>}<div className="form-actions"><button className="btn btn-secondary" onClick={() => save("Responded")} disabled={status === "loading"}>{t("respond", locale)}</button><button className="btn btn-primary" onClick={() => save("Confirmed")} disabled={status === "loading"}>{t("confirmBooking", locale)}</button><button className="btn btn-danger" onClick={() => save("Declined")} disabled={status === "loading"}>{t("declineInquiry", locale)}</button></div></div></FormState></section></div>; }

function DemoNotice() { const { locale } = useDemo(); return <div className="demo-notice" role="note"><ShieldAlert size={18} aria-hidden="true" /><div><strong>{t("demoNotice", locale)}</strong><p>{t("noTransactions", locale)} {t("noCredentials", locale)}</p></div></div>; }
function AdminPaymentList() { const { locale, payments, bookings, venues } = useDemo(); const [filter, setFilter] = useState(""); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = payments.filter((item) => (!filter || item.status === filter) && `${item.id} ${item.bookingId} ${bookings.find((booking) => booking.id === item.bookingId)?.customer || ""}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("paymentsAdmin", locale)} description={t("paymentRecords", locale)} /><DemoNotice /><div className="admin-list-toolbar"><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={query} onChange={(event) => setQuery(event.target.value)} /><select className="field" aria-label={t("paymentStatus", locale)} value={filter} onChange={(event) => setFilter(event.target.value)}><option value="">{t("allStatuses", locale)}</option>{["Success", "Failure", "Pending", "Refunded"].map((value) => <option key={value} value={value}>{t(value.toLowerCase(), locale)}</option>)}</select></div><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query || !!filter} emptyKey="noTransactions"><div className="admin-record-list">{filtered.map((payment) => { const booking = bookings.find((item) => item.id === payment.bookingId); return <article className="card admin-record" key={payment.id}><div><p className="eyebrow">{t("sample", locale)} · {formatDate(payment.date, locale)}</p><h2>{payment.id} · {t(payment.kind.toLowerCase(), locale)}</h2><p className="muted">{booking?.customer} · {venues.find((venue) => venue.id === booking?.venueId)?.name} · {payment.bookingId}</p></div><div className="admin-record-actions"><StatusBadge status={payment.status} locale={locale} /><strong>{formatETB(payment.amount, locale)}</strong><Link className="btn btn-secondary" href={`/admin/payments/${payment.id}`}>{t("viewDetails", locale)}</Link></div></article>; })}</div></ListState></div>; }
function AdminPaymentDetail({ paymentId }: { paymentId: string }) { const demo = useDemo(); const { locale } = demo; const payment = demo.payments.find((item) => item.id === paymentId); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); if (!payment) return <section className="card"><DemoNotice /><h1>{t("notFound", locale)}</h1><Link href="/admin/payments">{t("paymentsAdmin", locale)}</Link></section>; const currentPayment = payment; const booking = demo.bookings.find((item) => item.id === payment.bookingId); const venue = demo.venues.find((item) => item.id === booking?.venueId); function refund() { setStatus("loading"); setMessage(""); setTimeout(() => { demo.recordRefund(currentPayment.id); setStatus("success"); setMessage(t("refundMock", locale)); }, 220); } return <div className="page-stack"><div className="breadcrumbs"><Link href="/admin/payments">{t("paymentsAdmin", locale)}</Link><span>/</span><span>{payment.id}</span></div><PageTitle title={t("paymentDetails", locale)} description={t("sampleReceipt", locale)} /><DemoNotice /><section className="card payment-detail"><div className="card-title-row"><div><p className="eyebrow">{t("sample", locale)} · {payment.id}</p><h2>{t(payment.kind.toLowerCase(), locale)}</h2></div><StatusBadge status={payment.status} locale={locale} /></div><dl className="detail-list"><div><dt>{t("customer", locale)}</dt><dd>{booking?.customer || "—"}</dd></div><div><dt>{t("venue", locale)}</dt><dd>{venue?.name || "—"}</dd></div><div><dt>{t("booking", locale)}</dt><dd>{payment.bookingId}</dd></div><div><dt>{t("paymentDate", locale)}</dt><dd>{formatDate(payment.date, locale)}</dd></div><div><dt>{t("amount", locale)}</dt><dd>{formatETB(payment.amount, locale)}</dd></div></dl><FormState status={status} locale={locale} message={message}><div className="form-actions"><button className="btn btn-secondary" type="button" onClick={() => window.print()}><Printer size={15} aria-hidden="true" />{t("print", locale)}</button>{payment.status === "Success" && <button className="btn btn-danger" type="button" onClick={refund} disabled={status === "loading"}>{t("recordRefund", locale)}</button>}</div><p className="small-note">{t("refundOnly", locale)}</p></FormState></section></div>; }

function AdminRevenueModel() { const demo = useDemo(); const { locale } = demo; const [mode, setMode] = useState(demo.commissionMode); const [commission, setCommission] = useState(String(demo.commissionValue)); const [overrides, setOverrides] = useState(demo.venueCommissionOverrides); const [leadFees, setLeadFees] = useState(demo.leadFeesByCategory); const [feeTiming, setFeeTiming] = useState(demo.feeTiming); const [selectedVenue, setSelectedVenue] = useState(demo.venues[0]?.id || ""); const [overrideValue, setOverrideValue] = useState(String(demo.venueCommissionOverrides[demo.venues[0]?.id || ""] ?? "")); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); const [errors, setErrors] = useState(""); const [adjust, setAdjust] = useState<Record<string, string>>({}); const [feeQuery, setFeeQuery] = useState(""); const filteredFees = demo.fees.filter((fee) => `${fee.id} ${fee.vendorId} ${fee.inquiryId}`.toLowerCase().includes(feeQuery.toLowerCase())); const loading = useLoading(); const billed = demo.fees.reduce((sum, fee) => sum + fee.amount, 0); const collected = demo.fees.filter((fee) => fee.status === "Paid").reduce((sum, fee) => sum + fee.amount, 0); const outstanding = demo.fees.filter((fee) => fee.status === "Outstanding").reduce((sum, fee) => sum + fee.amount, 0);
  function save(event: React.FormEvent) { event.preventDefault(); const amount = Number(commission); if (!Number.isFinite(amount) || amount < 0 || (mode === "percentage" && amount > 100)) { setErrors(t("numberError", locale)); setStatus("error"); setMessage(t("errorKeep", locale)); return; } if (Object.values(leadFees).some((value) => !Number.isFinite(value) || value < 0)) { setErrors(t("numberError", locale)); setStatus("error"); setMessage(t("errorKeep", locale)); return; } setErrors(""); setStatus("loading"); setMessage(""); setTimeout(() => { const nextOverrides = { ...overrides }; if (selectedVenue && overrideValue !== "") nextOverrides[selectedVenue] = Number(overrideValue); demo.saveRevenueModel(mode, amount, nextOverrides, leadFees); demo.setFeeTiming(feeTiming); setStatus("success"); setMessage(t("actionSaved", locale)); }, 220); }
  function feeAction(fee: FeeStatement, next: FeeStatement["status"], amount?: number) { if (amount !== undefined && (!Number.isFinite(amount) || amount < 0)) { setStatus("error"); setMessage(t("numberError", locale)); return; } setStatus("loading"); setTimeout(() => { demo.setFeeRecord(fee.id, next, amount); setStatus("success"); setMessage(t("auditRecord", locale)); }, 180); }
  return <div className="page-stack"><PageTitle title={t("adminRevenueTitle", locale)} description={t("adminRevenueModelHelp", locale)} /><DemoNotice /><div className="stats-grid"><StatCard title={t("revenueBilled", locale)} value={formatETB(billed, locale)} icon={CircleDollarSign} /><StatCard title={t("revenueCollected", locale)} value={formatETB(collected, locale)} icon={CheckCircle2} /><StatCard title={t("revenueOutstanding", locale)} value={formatETB(outstanding, locale)} icon={Wallet} /></div>
    <FormState status={status} locale={locale} message={message}><form className="card revenue-settings-form" onSubmit={save} noValidate><h2>{t("commission", locale)} · {t("global", locale)}</h2><div className="admin-form-grid"><div><label className="label" htmlFor="commission-mode">{t("commissionMode", locale)}</label><select id="commission-mode" className="field" value={mode} onChange={(event) => setMode(event.target.value as typeof mode)}><option value="percentage">{t("percentage", locale)}</option><option value="fixed">{t("fixedFee", locale)}</option></select></div><Field label={t("commissionValue", locale)} id="commission-value" type="number" min="0" value={commission} onChange={setCommission} error={errors} /><div><label className="label" htmlFor="revenue-fee-timing">{t("feeTiming", locale)}</label><select id="revenue-fee-timing" className="field" value={feeTiming} onChange={(event) => setFeeTiming(event.target.value as typeof feeTiming)}><option value="inquiry sent">{t("chargeInquiry", locale)}</option><option value="vendor confirms">{t("chargeVendor", locale)}</option><option value="admin confirms">{t("chargeAdmin", locale)}</option></select></div><div><label className="label" htmlFor="override-venue">{t("perVenue", locale)} · {t("commission", locale)}</label><select id="override-venue" className="field" value={selectedVenue} onChange={(event) => { setSelectedVenue(event.target.value); setOverrideValue(String(overrides[event.target.value] ?? "")); }}><option value="">{t("global", locale)}</option>{demo.venues.map((venue, index) => <option key={`${venue.id}-${index}`} value={venue.id}>{venue.name}</option>)}</select><input className="field mt-2" type="number" min="0" aria-label={t("venueCommissionOverride", locale)} value={overrideValue} onChange={(event) => setOverrideValue(event.target.value)} placeholder={t("useGlobal", locale)} /></div></div><h3>{t("categoryFee", locale)}</h3><div className="admin-category-fees">{demo.categories.map((category) => <label key={category}>{categoryLabel(category, locale)}<span className="currency-input"><span>{t("etb", locale)}</span><input className="field" type="number" min="0" aria-label={`${t("leadFee", locale)}: ${categoryLabel(category, locale)}`} value={leadFees[category] ?? 0} onChange={(event) => setLeadFees((current) => ({ ...current, [category]: Number(event.target.value) }))} /></span></label>)}</div><button className="btn btn-primary" type="submit" disabled={status === "loading"}>{t("saveChanges", locale)}</button></form></FormState>
    <section className="page-stack"><h2>{t("feeStatements", locale)}</h2><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={feeQuery} onChange={(event) => setFeeQuery(event.target.value)} /><ListState locale={locale} items={filteredFees.length} loading={loading} noResults={!!feeQuery} emptyKey="noFees"><div className="stacked-list">{filteredFees.map((fee) => <article className="card admin-fee-row" key={fee.id}><div><p className="eyebrow">{t("sample", locale)} · {formatDate(fee.date, locale)}</p><h3>{fee.id} · {demo.vendors.find((vendor) => vendor.id === fee.vendorId)?.name}</h3><p className="small-note">{t("inquiry", locale)} {fee.inquiryId} · {formatETB(fee.amount, locale)}</p></div><div className="admin-fee-actions"><StatusBadge status={fee.status} locale={locale} /><input className="field" type="number" min="0" aria-label={`${t("adjustFee", locale)} ${fee.id}`} value={adjust[fee.id] ?? String(fee.amount)} onChange={(event) => setAdjust((current) => ({ ...current, [fee.id]: event.target.value }))} /><button type="button" className="btn btn-secondary" onClick={() => feeAction(fee, fee.status, Number(adjust[fee.id] ?? fee.amount))}>{t("adjustFee", locale)}</button>{fee.status !== "Waived" && <button type="button" className="btn btn-danger" onClick={() => feeAction(fee, "Waived")}>{t("waiveFee", locale)}</button>}{fee.status === "Outstanding" && <button type="button" className="btn btn-primary" onClick={() => feeAction(fee, "Paid")}>{t("markPaid", locale)}</button>}</div></article>)}</div></ListState></section>
  </div>;
}

function AdminReports() {
  const demo = useDemo();
  const { locale } = demo;
  const [report, setReport] = useState<"bookings" | "fees" | "vendors" | "venues" | "inquiries">("bookings");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [query, setQuery] = useState("");
  const [generated, setGenerated] = useState(false);
  const inRange = (date: string) => (!from || date >= from) && (!to || date <= to);
  const reportHeaderKeys = report === "bookings" ? ["booking", "customer", "venue", "date", "status", "source"]
    : report === "inquiries" ? ["inquiry", "customer", "vendor", "date", "status"]
    : report === "fees" ? ["feeStatement", "vendor", "date", "status", "amount"]
    : report === "vendors" ? ["category", "vendors", "activeVendors", "revenueCollected"]
    : ["venue", "area", "capacity", "confirmedEvents", "revenue"];
  const rawRows: string[][] = report === "bookings"
    ? demo.bookings.filter((item) => inRange(item.eventDate)).map((item) => [item.id, item.customer, demo.venues.find((venue) => venue.id === item.venueId)?.name || "", item.eventDate, item.status, item.source])
    : report === "inquiries"
    ? demo.inquiries.filter((item) => inRange(item.eventDate)).map((item) => [item.id, item.customer, demo.vendors.find((vendor) => vendor.id === item.vendorId)?.name || "", item.eventDate, item.status])
    : report === "fees"
    ? demo.fees.filter((item) => inRange(item.date)).map((item) => [item.id, demo.vendors.find((vendor) => vendor.id === item.vendorId)?.name || "", item.date, item.status, formatETB(item.amount, locale)])
    : report === "vendors"
    ? demo.categories.map((category) => {
        const vendors = demo.vendors.filter((vendor) => vendor.category === category);
        const vendorIds = new Set(vendors.map((vendor) => vendor.id));
        const paidFees = demo.fees.filter((fee) => inRange(fee.date) && vendorIds.has(fee.vendorId) && fee.status === "Paid");
        return [categoryLabel(category, locale), formatNumber(vendors.length, locale), formatNumber(vendors.filter((vendor) => vendor.status === "Active").length, locale), formatETB(paidFees.reduce((sum, fee) => sum + fee.amount, 0), locale)];
      })
    : demo.venues.map((venue) => {
        const confirmed = demo.bookings.filter((booking) => booking.venueId === venue.id && inRange(booking.eventDate) && (booking.status === "Confirmed" || booking.status === "Completed"));
        return [venue.name, venue.area, formatNumber(venue.capacity, locale), formatNumber(confirmed.length, locale), formatETB(confirmed.reduce((sum, booking) => sum + booking.total, 0), locale)];
      });
  const rows = rawRows.filter((row) => row.join(" ").toLowerCase().includes(query.trim().toLowerCase()));
  function exportCsv() {
    const header = reportHeaderKeys.map((key) => t(key, locale));
    const csv = [header, ...rows].map((row) => row.map((field) => `"${String(field).replaceAll('"', '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url; anchor.download = `sample-${report}-report.csv`; anchor.click(); URL.revokeObjectURL(url);
    setGenerated(true);
  }
  return <div className="page-stack">
    <PageTitle title={t("reportsTitle", locale)} description={t("reportsUseSample", locale)} /><DemoNotice />
    <section className="card report-filters">
      <div><label className="label" htmlFor="report-type">{t("reportType", locale)}</label><select id="report-type" className="field" value={report} onChange={(event) => { setReport(event.target.value as typeof report); setGenerated(false); }}><option value="bookings">{t("reportBookings", locale)}</option><option value="fees">{t("reportRevenue", locale)}</option><option value="vendors">{t("reportVendors", locale)}</option><option value="venues">{t("reportVenues", locale)}</option><option value="inquiries">{t("reportInquiries", locale)}</option></select></div>
      <div><label className="label" htmlFor="report-from">{t("fromDate", locale)}</label><input id="report-from" className="field" type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></div><div><label className="label" htmlFor="report-to">{t("toDate", locale)}</label><input id="report-to" className="field" type="date" value={to} onChange={(event) => setTo(event.target.value)} /></div>
      <div><label className="label" htmlFor="report-search">{t("searchRecords", locale)}</label><input id="report-search" className="field" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("searchPlaceholder", locale)} /></div>
      <button className="btn btn-primary" type="button" onClick={() => setGenerated(true)}>{t("generateReport", locale)}</button>
    </section>
    <div className="report-actions"><button type="button" className="btn btn-secondary" onClick={exportCsv}><Download size={15} aria-hidden="true" />{t("exportCsv", locale)}</button><button type="button" className="btn btn-secondary" onClick={() => { setGenerated(true); window.print(); }}><FileText size={15} aria-hidden="true" />{t("exportPdf", locale)}</button><button type="button" className="btn btn-secondary" onClick={() => window.print()}><Printer size={15} aria-hidden="true" />{t("print", locale)}</button></div>
    {generated && <p className="inline-notice" role="status">{t("reportGenerated", locale)} · {formatNumber(rows.length, locale)}</p>}
    <ListState locale={locale} items={rows.length} loading={false} noResults={Boolean(from || to || query)} emptyKey="noData"><div className="responsive-table"><table><thead><tr>{reportHeaderKeys.map((key) => <th key={key}>{t(key, locale)}</th>)}</tr></thead><tbody>{rows.slice(0, 100).map((row, rowIndex) => <tr key={rowIndex}>{row.map((cell, cellIndex) => <td key={`${rowIndex}-${cellIndex}`} data-label={t(reportHeaderKeys[cellIndex], locale)}>{statusValues.includes(cell) ? <StatusBadge status={cell} locale={locale} /> : cell}</td>)}</tr>)}</tbody></table></div></ListState>
  </div>;
}

function AdminUsers() { const demo = useDemo(); const { locale } = demo; const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [role, setRole] = useState<AdminStaff["role"]>("Venue Manager"); const [permissions, setPermissions] = useState<string[]>([]); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = demo.staffAccounts.filter((item) => `${item.name} ${item.email} ${item.role}`.toLowerCase().includes(query.toLowerCase())); const permissionList = ["bookings", "calendar", "venues", "vendors", "inquiries", "payments", "revenue", "reports", "settings"];
  function create(event: React.FormEvent) { event.preventDefault(); if (!name.trim() || !/^\S+@\S+\.\S+$/.test(email)) { setStatus("error"); setMessage(t("errorKeep", locale)); return; } setStatus("loading"); setTimeout(() => { demo.saveStaffAccount({ id: `staff-${Date.now()}`, name: name.trim(), email: email.trim(), role, permissions: permissions.length ? permissions : role === "Super Admin" ? ["all"] : [] }); setName(""); setEmail(""); setPermissions([]); setStatus("success"); setMessage(t("actionSaved", locale)); }, 220); }
  return <div className="page-stack"><PageTitle title={t("usersRoles", locale)} description={t("userRoleHelp", locale)} /><FormState status={status} locale={locale} message={message}><form className="card admin-form-grid" onSubmit={create} noValidate><Field label={t("fullName", locale)} id="staff-name" value={name} onChange={setName} /><Field label={t("email", locale)} id="staff-email" type="email" value={email} onChange={setEmail} /><div><label className="label" htmlFor="staff-role-select">{t("role", locale)}</label><select id="staff-role-select" className="field" value={role} onChange={(event) => setRole(event.target.value as AdminStaff["role"])}>{(["Super Admin", "Venue Manager", "Vendor Manager", "Finance"] as const).map((item) => <option key={item} value={item}>{t(item === "Super Admin" ? "superAdmin" : item === "Venue Manager" ? "venueManager" : item === "Vendor Manager" ? "vendorManager" : "finance", locale)}</option>)}</select></div><fieldset className="admin-permissions admin-form-full"><legend>{t("userPermissions", locale)}</legend><div className="permission-grid">{permissionList.map((item) => <label key={item}><input type="checkbox" checked={permissions.includes(item)} onChange={(event) => setPermissions((current) => event.target.checked ? [...current, item] : current.filter((entry) => entry !== item))} />{t(item, locale)}</label>)}</div></fieldset><div className="admin-form-full"><button className="btn btn-primary" type="submit" disabled={status === "loading"}>{t("createAccount", locale)}</button></div></form></FormState><label className="label" htmlFor="staff-search">{t("search", locale)}</label><input id="staff-search" className="field" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("searchPlaceholder", locale)} /><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query} emptyKey="noStaff"><div className="admin-record-list">{filtered.map((account) => <StaffRow account={account} key={account.id} />)}</div></ListState></div>;
}
function StaffRow({ account }: { account: AdminStaff }) { const demo = useDemo(); const { locale } = demo; const [role, setRole] = useState(account.role); return <article className="card admin-record"><div><h2>{account.name}</h2><p>{account.email}</p><p className="small-note">{t("userPermissions", locale)}: {account.permissions.join(", ") || t("none", locale)}</p></div><div className="admin-record-actions"><label className="sr-only" htmlFor={`role-${account.id}`}>{t("role", locale)}</label><select id={`role-${account.id}`} className="field" value={role} onChange={(event) => setRole(event.target.value as AdminStaff["role"])}>{(["Super Admin", "Venue Manager", "Vendor Manager", "Finance"] as const).map((item) => <option key={item} value={item}>{t(item === "Super Admin" ? "superAdmin" : item === "Venue Manager" ? "venueManager" : item === "Vendor Manager" ? "vendorManager" : "finance", locale)}</option>)}</select><button className="btn btn-secondary" type="button" onClick={() => demo.saveStaffAccount({ ...account, role })}>{t("saveChanges", locale)}</button></div></article>; }

function AdminNotifications() { const demo = useDemo(); const { locale } = demo; const [read, setRead] = useState<string[]>([]); const [query, setQuery] = useState(""); const loading = useLoading(); const titleKey: Record<string, string> = { "NT-1": "notificationBooking", "NT-2": "notificationVendor", "NT-3": "notificationCalendar" }; const filtered = mockNotifications.filter((item) => `${t(titleKey[item.id], locale)} ${t(`${titleKey[item.id]}Detail`, locale)}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("notificationCenter", locale)} description={t("notificationsHelp", locale)} /><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={query} onChange={(event) => setQuery(event.target.value)} /><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query} emptyKey="noNotifications"><div className="admin-record-list">{filtered.map((item) => <article className="card admin-record" key={item.id}><div><p className="eyebrow">{formatDate(item.date, locale)}</p><h2>{t(titleKey[item.id], locale)}</h2><p className="muted">{t(`${titleKey[item.id]}Detail`, locale)}</p></div><span className="tag">{read.includes(item.id) ? t("read", locale) : t("unread", locale)}</span><button type="button" className="btn btn-secondary" onClick={() => setRead((current) => current.includes(item.id) ? current : [...current, item.id])}>{t("markRead", locale)}</button></article>)}</div></ListState><Link className="text-link" href="/notifications">{t("customerNotifications", locale)}</Link></div>; }
function AdminSettings() { const demo = useDemo(); const { locale } = demo; const [preferences, setPreferences] = useState(demo.notificationPreferences); const [venueRule, setVenueRule] = useState(demo.contactVenueAfterDeposit); const [vendorRule, setVendorRule] = useState(demo.contactVendorAfterAcceptance); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); function save(event: React.FormEvent) { event.preventDefault(); setStatus("loading"); setTimeout(() => { demo.setContactRules(venueRule, vendorRule); demo.saveNotificationPreferences(preferences); demo.addAuditRecord("auditSystemSettingsSaved", "Contact visibility and notification preferences"); setStatus("success"); setMessage(t("settingsSaved", locale)); }, 220); } return <div className="page-stack"><PageTitle title={t("settingsLabel", locale)} description={t("settingsHelp", locale)} /><FormState status={status} locale={locale} message={message}><form className="card form-card" onSubmit={save}><h2>{t("contactVisibility", locale)}</h2><label className="label" htmlFor="venue-contact-rule">{t("contactRuleVenue", locale)}</label><select id="venue-contact-rule" className="field" value={venueRule ? "after" : "hidden"} onChange={(event) => setVenueRule(event.target.value === "after")}><option value="after">{t("afterDeposit", locale)}</option><option value="hidden">{t("maskedContact", locale)}</option></select><label className="label" htmlFor="vendor-contact-rule">{t("contactRuleVendor", locale)}</label><select id="vendor-contact-rule" className="field" value={vendorRule ? "after" : "hidden"} onChange={(event) => setVendorRule(event.target.value === "after")}><option value="after">{t("afterAcceptance", locale)}</option><option value="hidden">{t("maskedContact", locale)}</option></select><h2 className="mt-6">{t("notificationSettings", locale)}</h2><div className="permission-grid">{Object.entries(preferences).map(([key, value]) => <label key={key}><input type="checkbox" checked={value} onChange={(event) => setPreferences((current) => ({ ...current, [key]: event.target.checked }))} />{t(`notify${key[0].toUpperCase()}${key.slice(1)}`, locale)}</label>)}</div><h2 className="mt-6">{t("systemStatus", locale)}</h2><p className="inline-notice"><ShieldAlert size={15} aria-hidden="true" />{t("backupStatusText", locale)}</p><p>{t("availableLanguages", locale)}: {t("languageEnglish", locale)} · {t("languageAmharic", locale)}</p><button className="btn btn-primary" type="submit" disabled={status === "loading"}>{t("saveChanges", locale)}</button></form></FormState></div>; }
function AdminAudit() { const { locale, auditLog } = useDemo(); const [query, setQuery] = useState(""); const loading = useLoading(); const filtered = auditLog.filter((record) => `${t(record.action, locale)} ${record.details} ${record.actor}`.toLowerCase().includes(query.toLowerCase())); return <div className="page-stack"><PageTitle title={t("auditLog", locale)} description={t("auditHelp", locale)} /><input className="field" aria-label={t("searchRecords", locale)} placeholder={t("searchPlaceholder", locale)} value={query} onChange={(event) => setQuery(event.target.value)} /><ListState locale={locale} items={filtered.length} loading={loading} noResults={!!query} emptyKey="noAudit"><div className="admin-record-list">{filtered.map((record) => <AuditRow record={record} key={record.id} />)}</div></ListState></div>; }
function AuditRow({ record }: { record: AuditRecord }) { const { locale } = useDemo(); return <article className="card admin-record"><div><p className="eyebrow">{formatDate(record.at, locale)} · {staffRoleLabel(record.actor, locale)}</p><h2>{t(record.action, locale)}</h2><p className="muted">{record.details}</p></div><Activity size={18} aria-hidden="true" /></article>; }
function AdminContent() { const demo = useDemo(); const { locale } = demo; const [content, setContent] = useState(demo.staticContent); const [status, setStatus] = useState<FormStatus>("idle"); const [message, setMessage] = useState(""); function save(event: React.FormEvent) { event.preventDefault(); if (Object.values(content).some((value) => !value.trim())) { setStatus("error"); setMessage(t("errorKeep", locale)); return; } setStatus("loading"); setTimeout(() => { demo.saveStaticContent(content); setStatus("success"); setMessage(t("actionSaved", locale)); }, 220); } return <div className="page-stack"><PageTitle title={t("contentEditor", locale)} description={t("contentEditorHelp", locale)} /><FormState status={status} locale={locale} message={message}><form className="card form-card" onSubmit={save}>{(["faq", "terms", "privacy"] as const).map((key) => <section className="content-language-edit" key={key}><h2>{t(key, locale)}</h2><label className="label" htmlFor={`${key}-en`}>{t("languageEnglish", locale)}</label><textarea id={`${key}-en`} className="field textarea" value={content[`${key}_en`] || ""} onChange={(event) => setContent((current) => ({ ...current, [`${key}_en`]: event.target.value }))} /><label className="label" htmlFor={`${key}-am`}>{t("languageAmharic", locale)}</label><textarea id={`${key}-am`} className="field textarea" value={content[`${key}_am`] || ""} onChange={(event) => setContent((current) => ({ ...current, [`${key}_am`]: event.target.value }))} /></section>)}<button className="btn btn-primary" type="submit" disabled={status === "loading"}>{t("saveChanges", locale)}</button></form></FormState></div>; }
